// 1. Format existing SyaCo solutions
const solInput = $('Get Current Solutions').first()?.json || [];
const rawSolutions = Array.isArray(solInput) ? solInput : (solInput.data || [solInput]);
const currentSolutions = rawSolutions.map(s => ({
  id: s.id,
  titleEn: s.titleEn || '',
  titleTh: s.titleTh || '',
  descEn: s.content?.en?.hero?.description || s.descEn || '',
  descTh: s.content?.th?.hero?.description || s.descTh || ''
})).filter(s => s.titleEn || s.titleTh);

// 2. Parse RSS Feeds
function parseRss(xmlText, sourceName) {
  if (!xmlText || typeof xmlText !== 'string') return [];
  const items = [];
  const itemBlocks = xmlText.match(/<item[\s\S]*?<\/item>/gi) || [];
  for (const block of itemBlocks) {
    const titleMatch = block.match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/i);
    const descMatch = block.match(/<description>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/description>/i);
    const linkMatch = block.match(/<link>([\s\S]*?)<\/link>/i);
    const title = (titleMatch ? titleMatch[1] : '').replace(/<!\[CDATA\[|\]\]>/g, '').trim();
    const desc = (descMatch ? descMatch[1] : '').replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, '').trim();
    const link = (linkMatch ? linkMatch[1] : '').trim();
    if (title) {
      items.push({ source: sourceName, title, desc: desc.slice(0, 300), link });
    }
  }
  return items;
}

const tttFeedText = $('Fetch TechTalkThai Feed').first()?.json?.data || $('Fetch TechTalkThai Feed').first()?.json || '';
const bnFeedText = $('Fetch Blognone Feed').first()?.json?.data || $('Fetch Blognone Feed').first()?.json || '';

const allArticles = [
  ...parseRss(tttFeedText, 'TechTalkThai'),
  ...parseRss(bnFeedText, 'Blognone')
];

// 3. Filter enterprise B2B tech trends
const keywords = ['erp', 'plc', 'data pipeline', 'legacy', 'modbus', 'iot', 'factory', 'automation', 'cloud', 'migration', 'database', 'warehouse', 'logistics', 'tracking', 'api', 'scada', 'sensor', 'sap', 'middleware', 'integration', 'devops'];
const filteredTrends = allArticles.filter(a => {
  const text = (a.title + ' ' + a.desc).toLowerCase();
  return keywords.some(k => text.includes(k));
}).slice(0, 8);

// 4. Construct Gemini Prompt
const prompt = [
  'You are the Principal Enterprise Solution Architect for SyaCo (https://www.syaco.co.th), a premier enterprise software and digital transformation engineering firm in Thailand.',
  '',
  '## Context: Current SyaCo Solutions Catalog',
  JSON.stringify(currentSolutions, null, 2),
  '',
  '## Context: Latest Enterprise Tech Trends & Discussions',
  JSON.stringify(filteredTrends, null, 2),
  '',
  '## Task: Propose One High-Value Adjacent Solution',
  'Identify a market gap and propose ONE high-value adjacent enterprise solution that builds upon one of SyaCo\'s existing solutions (1 logical step expansion, not a random pivot).',
  '',
  '## Strict Requirements:',
  '1. Strict Bilingual (Thai and English) for all titles, descriptions, results, problems, and target audience.',
  '2. Results section: 2-4 qualitative enterprise value outcomes. DO NOT FABRICATE QUANTITATIVE STATISTICS OR FAKE METRICS (e.g., do not say "reduces cost by 45%"). Focus on concrete architectural, operational, and business reliability improvements.',
  '3. Problems section: 3-5 real-world pain points faced by enterprise managers / CTOs.',
  '4. Target audience: 3-4 specific stakeholder roles in mid-to-large organizations in Thailand/Southeast Asia.',
  '5. Features: 2-4 core technological features (labelTh, labelEn).',
  '6. Base Solution: Must reference an existing SyaCo solution ID that this proposal extends.',
  '',
  'Return valid JSON only matching the schema.'
].join('\n');

const geminiBody = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0.7,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        baseSolutionId: { type: 'STRING' },
        titleTh: { type: 'STRING' },
        titleEn: { type: 'STRING' },
        descriptionTh: { type: 'STRING' },
        descriptionEn: { type: 'STRING' },
        rationale: { type: 'STRING' },
        features: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              labelTh: { type: 'STRING' },
              labelEn: { type: 'STRING' }
            },
            required: ['labelTh', 'labelEn']
          }
        },
        contentAi: {
          type: 'OBJECT',
          properties: {
            th: {
              type: 'OBJECT',
              properties: {
                results: { type: 'ARRAY', items: { type: 'STRING' } },
                problems: { type: 'ARRAY', items: { type: 'STRING' } },
                targetAudience: { type: 'ARRAY', items: { type: 'STRING' } }
              },
              required: ['results', 'problems', 'targetAudience']
            },
            en: {
              type: 'OBJECT',
              properties: {
                results: { type: 'ARRAY', items: { type: 'STRING' } },
                problems: { type: 'ARRAY', items: { type: 'STRING' } },
                targetAudience: { type: 'ARRAY', items: { type: 'STRING' } }
              },
              required: ['results', 'problems', 'targetAudience']
            }
          },
          required: ['th', 'en']
        }
      },
      required: ['baseSolutionId', 'titleTh', 'titleEn', 'descriptionTh', 'descriptionEn', 'rationale', 'features', 'contentAi']
    }
  }
};

return [{ json: { geminiBody } }];

const candidates = $input.first()?.json?.candidates || [];
const rawText = candidates[0]?.content?.parts?.[0]?.text || '{}';
let data = {};
try {
  data = JSON.parse(rawText);
} catch (e) {
  throw new Error('Failed to parse Gemini JSON output: ' + e.message);
}

return [{
  json: {
    base_solution_id: String(data.baseSolutionId || ''),
    title_th: String(data.titleTh || '').trim(),
    title_en: String(data.titleEn || '').trim(),
    description_th: String(data.descriptionTh || '').trim(),
    description_en: String(data.descriptionEn || '').trim(),
    rationale: String(data.rationale || '').trim(),
    features_json: JSON.stringify(data.features || []),
    content_ai_json: JSON.stringify(data.contentAi || { th: {}, en: {} }),
    features: data.features || [],
    content_ai: data.contentAi || { th: {}, en: {} }
  }
}];

